  show Elem{attributes, name, content} =
    "<" <> name <> as <> ">" <> (foldMap show content) <> "</" <> name <> ">"
      where as = (<>) " " . intercalate ";" . fmap (\(k, v) -> k <> "=" <> v) . toList $ attributes
  show (Leaf t) = t

